Q: random number between 0 - 8 JavaScript A: <p>Your code already works, just add line breaks:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function randomize() {

    var arr = []
    while(arr.length &lt; 40){
        var randomnumber=Math.floor((Math.random() * 9)) // 0-8 is 9 numbers
        arr.push(randomnumber) 
    }
    document.getElementById("Output").innerHTML = arr.join('&lt;br&gt;'); // Add line break between numbers

}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;h1&gt;This is a page for randomize number between 0 - 8 &lt;/h1&gt; &lt;br /&gt;

&lt;button onclick="randomize()"&gt;Random number&lt;/button&gt;

&lt;p id="Output"&gt;&lt;/p&gt;</code></pre>
</div>
</div>
</p>
